import React, { useState, createContext, useContext } from "react";
import { Cog6ToothIcon, HomeIcon, FlagIcon, ChartBarIcon } from "@heroicons/react/24/outline";
import { UserContext } from "./UserContext";
import FinancialInputs from "./FinancialInputs";

export const SectionContext = createContext();

const Sidebar = ({ activeSection, setActiveSection }) => (
  <aside className="w-24 bg-white h-full flex flex-col items-center py-6 shadow-md">
    <div className="mb-8 flex flex-col gap-6 items-center">
      <button
        className={`flex flex-col items-center h-16 w-16 justify-center rounded-lg ${activeSection === 'home' ? 'bg-primary/10 border-primary border' : ''}`}
        onClick={() => setActiveSection('home')}
        title="Home"
      >
        <HomeIcon className={`h-7 w-7 mb-1 ${activeSection === 'home' ? 'text-primary' : 'text-gray-400'}`} />
        <span className={`text-xs font-medium ${activeSection === 'home' ? 'text-primary' : 'text-gray-400'}`}>Home</span>
      </button>
      <button
        className={`flex flex-col items-center h-16 w-16 justify-center rounded-lg ${activeSection === 'goals' ? 'bg-primary/10 border-primary border' : ''}`}
        onClick={() => setActiveSection('goals')}
        title="Goals"
      >
        <FlagIcon className={`h-7 w-7 mb-1 ${activeSection === 'goals' ? 'text-primary' : 'text-gray-400'}`} />
        <span className={`text-xs font-medium ${activeSection === 'goals' ? 'text-primary' : 'text-gray-400'}`}>Goals</span>
      </button>
      <button
        className={`flex flex-col items-center h-16 w-16 justify-center rounded-lg ${activeSection === 'overview' ? 'bg-primary/10 border-primary border' : ''}`}
        onClick={() => setActiveSection('overview')}
        title="Full Overview"
      >
        <ChartBarIcon className={`h-7 w-7 mb-1 ${activeSection === 'overview' ? 'text-primary' : 'text-gray-400'}`} />
        <span className={`text-xs font-medium ${activeSection === 'overview' ? 'text-primary' : 'text-gray-400'}`}>Overview</span>
      </button>
    </div>
  </aside>
);

const Topbar = ({ income, setIncome, currentSavings, setCurrentSavings }) => {
  const { logout } = useContext(UserContext);

  return (
    <header className="flex items-center justify-between px-8 py-4 bg-white shadow-sm">
      <h1 className="text-2xl font-bold tracking-tight text-primary">Proxima</h1>
      <div className="flex items-center gap-6">
        <FinancialInputs 
          income={income} 
          setIncome={setIncome}
          currentSavings={currentSavings}
          setCurrentSavings={setCurrentSavings}
        />
        <div className="flex items-center gap-4">
          <button 
            onClick={logout} 
            className="px-4 py-2 rounded-lg bg-gradient-to-r from-gray-50 to-gray-100 text-gray-700 font-medium hover:from-gray-100 hover:to-gray-200 transition-all duration-200 shadow-sm"
          >
            Logout
          </button>
          <Cog6ToothIcon className="h-7 w-7 text-gray-400 cursor-pointer hover:text-gray-600 transition-colors duration-200" />
        </div>
      </div>
    </header>
  );
};

const Layout = ({ children, income, setIncome, currentSavings, setCurrentSavings }) => {
  const [activeSection, setActiveSection] = useState('home');

  return (
    <SectionContext.Provider value={{ activeSection, setActiveSection }}>
      <div className="flex h-screen bg-gradient-to-br from-blue-50 via-white to-emerald-50">
        <Sidebar activeSection={activeSection} setActiveSection={setActiveSection} />
        <div className="flex-1 flex flex-col">
          <Topbar 
            income={income} 
            setIncome={setIncome}
            currentSavings={currentSavings}
            setCurrentSavings={setCurrentSavings}
          />
          <main className="flex-1 p-8 overflow-y-auto">{children}</main>
        </div>
      </div>
    </SectionContext.Provider>
  );
};

export default Layout;
